package com.idfc.ai.runbook.artifact; import com.idfc.ai.runbook.config.RunbookProperties; import java.nio.file.*; import java.io.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class FileSystemBaselineStore implements BaselineStore { private final Path root; public FileSystemBaselineStore(RunbookProperties p){root=Path.of(p.getArtifactsRoot()).resolve("baselines");} public Optional<String> loadLatestSuccessful(String s,String e){try{Path p=root.resolve(s+"-"+e+".json");return Files.exists(p)?Optional.of(Files.readString(p)):Optional.empty();}catch(IOException x){throw new IllegalStateException(x);}} public void saveSuccessful(String s,String e,String v){try{Files.createDirectories(root);Files.writeString(root.resolve(s+"-"+e+".json"),v);}catch(IOException x){throw new IllegalStateException(x);}} }
